import euc

F.update(MARC='pgl/data/tlg0007/tlg022/*grc*.xml', CLEO='f1k/data/tlg1272/tlg001/*grc1.xml',
 DC='f1k/data/tlg0552/tlg002/*grc1.xml', SC='f1k/data/tlg0552/tlg001/*grc1.xml', METH='f1k/data/tlg0552/tlg010/*grc1.xml',
 AREN='f1k/data/tlg0552/tlg006/*grc1.xml', QP='f1k/data/tlg0552/tlg007/*grc1.xml', METR='f1k/data/tlg0559/tlg006/*grc1.xml',
 DIOP='f1k/data/tlg0559/tlg007/*grc1.xml', CAT='f1k/data/tlg0559/tlg005/*grc1.xml', ARIS='f1k/data/tlg1181/tlg001/*grc1.xml')

def E(book, num, head, tr, note=None, i=None):
    add(i or f'E{book}_{num}', f'Евклид, «Начала», {head}', euc.enun(book, num), tr, note)

# ---- основания
add('EU_DEF', 'Евклид, «Начала», I, определения 1–4, 15, 23',
    [euc.div(1, 'def', 1), euc.div(1, 'def', 2), euc.div(1, 'def', 3), euc.div(1, 'def', 4), euc.div(1, 'def', 15), euc.div(1, 'def', 23)],
    '1. Точка есть то, что не имеет частей. 2. Линия — длина без ширины. 3. Концы линии — точки. 4. Прямая линия — та, которая одинаково расположена по отношению к точкам на ней. '
    '15. Круг — плоская фигура, ограниченная одной линией, которая называется окружностью, такая, что все прямые, проведённые к этой окружности из одной точки внутри фигуры, равны между собой. '
    '23. Параллельные — это прямые, которые, находясь в одной плоскости и будучи неограниченно продолжены в обе стороны, ни с той, ни с другой стороны не встречаются друг с другом.',
    'Определение прямой (4) загадочно уже для античных комментаторов. Его толкуют так: прямая «лежит ровно», ни одна её точка не выдаётся — как натянутая нить или луч зрения.')
POST = euc.div(1, 'post')
add('EU_POST', 'Евклид, «Начала», I, постулаты (требования) 1–5',
    [POST.split(' καὶ πεπερασμένην')[0], 'καὶ πεπερασμένην' + POST.split('καὶ πεπερασμένην')[1].split(' καὶ παντὶ')[0],
     'καὶ παντὶ' + POST.split('καὶ παντὶ')[1].split(' καὶ πάσας')[0], 'καὶ πάσας' + POST.split('καὶ πάσας')[1].split(' καὶ ἐὰν')[0],
     'καὶ ἐὰν' + POST.split('καὶ ἐὰν')[1]],
    '«Допустим [букв. „пусть будет потребовано“]: 1) от всякой точки до всякой точки можно провести прямую линию; 2) ограниченную прямую можно непрерывно продолжать по прямой; '
    '3) из всякого центра всяким раствором [радиусом] можно описать круг; 4) все прямые углы равны между собой; '
    '5) если прямая, падающая на две прямые, образует внутренние и по одну сторону углы, [в сумме] меньшие двух прямых, то эти две прямые, неограниченно продолженные, встретятся с той стороны, где углы меньше двух прямых».',
    'Ἠιτήσθω — повелительное наклонение: «пусть будет потребовано». Постулаты 1–3 — это, по сути, разрешение пользоваться линейкой и циркулем. Пятый — знаменитый постулат о параллельных.')
CN = euc.div(1, 'comm_not')
add('EU_CN', 'Евклид, «Начала», I, общие понятия (аксиомы)', CN,
    '1) Равные одному и тому же равны и между собой. 2) Если к равным прибавить равные, то и целые будут равны. 3) Если от равных отнять равные, то остатки будут равны. '
    '4) Если к неравным прибавить равные, то целые будут неравны. 5) Удвоенные одного и того же равны между собой. 6) Половины одного и того же равны между собой. '
    '7) Совмещающиеся друг с другом равны между собой. 8) Целое больше части. 9) Две прямые не ограничивают пространства.',
    'В издании Гейберга подлинными считаются 1–3, 7 и 8; остальные (4–6, 9) — позднейшие добавления. Аксиома 7 («совмещающиеся равны») узаконивает доказательство наложением.')

# ---- I.1 целиком, по частям
P1 = euc.div(1, 'prop', 1)
def cut(s, a, b=None):
    i = s.index(a); j = s.index(b, i) if b else len(s)
    return s[i:j].strip()
parts = [
 ('πρότασις — формулировка', cut(P1, 'ἐπὶ τῆς δοθείσης', 'ἔστω ἡ')),
 ('ἔκθεσις — «выставление» данного', cut(P1, 'ἔστω ἡ', 'δεῖ δὴ')),
 ('διορισμός — что требуется', cut(P1, 'δεῖ δὴ', 'κέντρῳ μὲν')),
 ('κατασκευή — построение', cut(P1, 'κέντρῳ μὲν', 'καὶ ἐπεὶ')),
 ('ἀπόδειξις — доказательство', cut(P1, 'καὶ ἐπεὶ', 'Ἐπὶ τῆς δοθείσης ἄρα')),
 ('συμπέρασμα — заключение', cut(P1, 'Ἐπὶ τῆς δοθείσης ἄρα')),
]
add('E1_1_FULL', 'Евклид, «Начала», I, 1 — целиком, с разметкой шести частей предложения (по Проклу)',
    [f'RAW:**{lab}.** *{g}*' for lab, g in parts],
    '«На данной ограниченной прямой построить равносторонний треугольник. Пусть данная ограниченная прямая — АВ. Требуется на прямой АВ построить равносторонний треугольник. '
    'Из центра А раствором АВ опишем круг ВГД и из центра В раствором ВА опишем круг АГЕ; из точки Г, где круги пересекаются, к точкам А и В проведём прямые ГА и ГВ. '
    'Так как точка А — центр круга ГДВ, то АГ равна АВ; и так как точка В — центр круга ГАЕ, то ВГ равна ВА. Но доказано, что и ГА равна АВ; значит, каждая из ГА и ГВ равна АВ. '
    'А равные одному и тому же равны и между собой; значит, и ГА равна ГВ; следовательно, три прямые ГА, АВ, ВГ равны между собой. Итак, треугольник АВГ равносторонний и построен на данной ограниченной прямой АВ. '
    'Итак, на данной ограниченной прямой построен равносторонний треугольник, что и требовалось сделать».',
    'ὅπερ ἔδει ποιῆσαι — «что и требовалось сделать» (для задач на построение); ὅπερ ἔδει δεῖξαι — «что и требовалось доказать» (для теорем), отсюда латинское Q.E.D. Деление предложения на шесть частей описывает Прокл (Комментарий, 203). '
    'Слабое место, замеченное только в XIX в.: Евклид нигде не доказывает, что два круга вообще пересекаются. Для этого нужна аксиома непрерывности (её ввели Паш, Дедекинд и Гильберт).')

# ---- книга I
E(1, 4, 'I, 4 — первый признак равенства треугольников', '«Если в двух треугольниках две стороны соответственно равны двум сторонам и угол между равными сторонами равен углу, то и основание будет равно основанию, и треугольник — треугольнику, и остальные углы — остальным углам, каждый каждому, — те, против которых лежат равные стороны».')
E(1, 5, 'I, 5 — «ослиный мост»', '«В равнобедренных треугольниках углы при основании равны между собой, и если продолжить равные стороны, то углы под основанием будут равны между собой».',
  'Название pons asinorum («мост для ослов») — средневековое: на этой теореме «спотыкались» слабые ученики, а чертёж Евклида похож на мостик. Евдем приписывал утверждение Фалесу (§2 свода математики).')
E(1, 8, 'I, 8 — третий признак (по трём сторонам)', '«Если в двух треугольниках две стороны соответственно равны двум сторонам и основание равно основанию, то и угол между равными сторонами будет равен углу».')
E(1, 15, 'I, 15 — вертикальные углы', '«Если две прямые пересекаются, они образуют вертикальные углы, равные между собой».')
E(1, 20, 'I, 20 — неравенство треугольника', '«Во всяком треугольнике две стороны, как их ни выбирать, больше оставшейся».',
  'Прокл (Комментарий, 322) сообщает, что эпикурейцы смеялись над этой теоремой: её «знает даже осёл» — он идёт к сену прямо, а не по двум сторонам треугольника. Прокл отвечает: знать, что это так, и доказать, почему это так, — разные вещи.')
E(1, 29, 'I, 29 — первое применение пятого постулата', '«Прямая, падающая на параллельные прямые, образует равные накрест лежащие углы, внешний угол, равный внутреннему противолежащему, и внутренние односторонние углы, в сумме равные двум прямым».')
E(1, 32, 'I, 32 — сумма углов треугольника', '«Во всяком треугольнике при продолжении одной из сторон внешний угол равен двум внутренним, не смежным с ним, а три внутренних угла треугольника равны двум прямым».')
E(1, 35, 'I, 35 — параллелограммы с общим основанием', '«Параллелограммы, находящиеся на одном и том же основании и между одними и теми же параллельными, равны между собой».',
  '«Равны» у Евклида значит «равновелики» — равны по площади, хотя могут быть разной формы.')
E(1, 47, 'I, 47 — «теорема Пифагора»', '«В прямоугольных треугольниках квадрат на стороне, стягивающей прямой угол, равен [вместе взятым] квадратам на сторонах, заключающих прямой угол».',
  'Заметьте: Евклид говорит не о числах и не о «a² + b²», а о квадратах-фигурах, построенных на сторонах. И доказывает равенство площадей, а не вычисления. Имени Пифагора в «Началах» нет.')
E(1, 48, 'I, 48 — обратная теорема', '«Если в треугольнике квадрат на одной из сторон равен квадратам на двух остальных сторонах, то угол, заключённый между этими двумя сторонами, прямой».',
  'Именно обратная теорема нужна строителю: из длин 3, 4, 5 она гарантирует прямой угол.')

# ---- книга II
E(2, 4, 'II, 4 — «квадрат суммы»', '«Если прямая линия как-нибудь рассечена, то квадрат на всей [прямой] равен квадратам на отрезках вместе с дважды взятым прямоугольником, заключённым между отрезками».',
  'На языке алгебры: (a + b)² = a² + b² + 2ab. Но у Евклида это утверждение о площадях, видимое на одном чертеже.')
E(2, 11, 'II, 11 — деление в крайнем и среднем отношении (построение)', '«Данную прямую рассечь так, чтобы прямоугольник, заключённый между целой и одним из отрезков, был равен квадрату на оставшемся отрезке».')
E(2, 14, 'II, 14 — квадратура любого многоугольника', '«Построить квадрат, равный данной прямолинейной фигуре».',
  'Это вершина II книги: любой многоугольник можно превратить в равновеликий квадрат циркулем и линейкой. Отсюда вековая надежда «квадрировать» и круг.')

# ---- книга III
E(3, 1, 'III, 1', '«Найти центр данного круга».')
E(3, 20, 'III, 20 — центральный и вписанный угол', '«В круге угол при центре вдвое больше угла при окружности, если у этих углов одна и та же дуга в основании».')
E(3, 21, 'III, 21 — вписанные углы, опирающиеся на одну дугу', '«В круге углы в одном и том же сегменте равны между собой».')
E(3, 22, 'III, 22 — вписанный четырёхугольник', '«У четырёхугольников, вписанных в круги, противоположные углы вместе равны двум прямым».')
E(3, 31, 'III, 31 — угол в полукруге', '«В круге угол в полукруге — прямой, в большем сегменте — меньше прямого, в меньшем сегменте — больше прямого…»')
E(3, 35, 'III, 35 — пересекающиеся хорды', '«Если в круге две прямые пересекают друг друга, то прямоугольник, заключённый между отрезками одной, равен прямоугольнику, заключённому между отрезками другой».')

# ---- книга IV
E(4, 15, 'IV, 15 — правильный шестиугольник', '«В данный круг вписать равносторонний и равноугольный шестиугольник».',
  'В следствии к этому предложению Евклид отмечает: сторона шестиугольника равна радиусу круга. Поэтому циркуль, не меняя раствора, ровно шесть раз «шагает» по окружности.')
E(4, 16, 'IV, 16 — пятнадцатиугольник', '«В данный круг вписать равносторонний и равноугольный пятнадцатиугольник».',
  'Прокл (269) замечает, что пятнадцатиугольник нужен астрономии: угол наклона эклиптики к экватору тогда считали равным стороне пятнадцатиугольника, то есть 24°.')

# ---- книга VI
VI = euc.div(6, 'def')
